+/*
+ * Follow QUIC stream reassembly.
+ *
+ * Unlike TCP, a QUIC STREAM frame carries the absolute byte offset of its
+ * data within the stream, so the two directions of a stream can be reordered
+ * without any ambiguity and there is no sequence number wrap-around. The
+ * generic follow infrastructure only provides 32 bit "seq" fields, which is
+ * sufficient because the reassembly machinery in this dissector is limited to
+ * 32 bit stream offsets anyway (see desegment_quic_stream()).
+ *
+ * STREAM frames may arrive out of order, be retransmitted or overlap frames
+ * that were already seen. The code below mirrors the approach used by the TCP
+ * follower: contiguous data is appended to the payload right away, while data
+ * beyond a gap is parked on follow_info->fragments[] and flushed once the gap
+ * is filled. Retransmitted and fully overlapping data is discarded.
+ */
+
+/* Compare two pending fragments by stream offset, then by frame number. */
+static gint
+quic_follow_fragment_compare(gconstpointer a, gconstpointer b)
+{
+    const follow_record_t *fa = (const follow_record_t *)a;
+    const follow_record_t *fb = (const follow_record_t *)b;
+
+    if (fa->seq < fb->seq)
+        return -1;
+    if (fa->seq > fb->seq)
+        return 1;
+    if (fa->packet_num < fb->packet_num)
+        return -1;
+    if (fa->packet_num > fb->packet_num)
+        return 1;
+    return 0;
+}
+
+/*
+ * Try to append pending out of order fragments that are now contiguous with
+ * the next expected stream offset. Fragments that start before the expected
+ * offset are retransmissions: only the not yet seen tail is kept. Returns
+ * true if at least one fragment made progress.
+ */
+static bool
+quic_follow_flush_fragments(follow_info_t *follow_info, bool is_server)
+{
+    GList *fragment_entry;
+    follow_record_t *fragment;
+    bool progress = false;
+
+    while ((fragment_entry = g_list_first(follow_info->fragments[is_server])) != NULL) {
+        fragment = (follow_record_t *)fragment_entry->data;
+        uint32_t next_offset = follow_info->seq[is_server];
+        uint32_t frag_end = fragment->seq + fragment->data->len;
+
+        if (fragment->seq > next_offset) {
+            /* Still a gap before this fragment; the list is sorted by
+             * offset, so no later fragment can fit either. */
+            break;
+        }
+
+        if (frag_end <= next_offset) {
+            /* Fully retransmitted/duplicated data, drop it. */
+            g_byte_array_free(fragment->data, true);
+            g_free(fragment);
+            follow_info->fragments[is_server] =
+                g_list_delete_link(follow_info->fragments[is_server], fragment_entry);
+            progress = true;
+            continue;
+        }
+
+        if (fragment->seq < next_offset) {
+            /* Partial retransmission: keep only the new tail. */
+            uint32_t skip = next_offset - fragment->seq;
+            follow_record_t *tail = g_new0(follow_record_t, 1);
+
+            tail->is_server = is_server;
+            tail->packet_num = fragment->packet_num;
+            tail->abs_ts = fragment->abs_ts;
+            tail->seq = next_offset;
+            tail->data = g_byte_array_new();
+            g_byte_array_append(tail->data,
+                                fragment->data->data + skip,
+                                fragment->data->len - skip);
+
+            g_byte_array_free(fragment->data, true);
+            g_free(fragment);
+            follow_info->fragments[is_server] =
+                g_list_delete_link(follow_info->fragments[is_server], fragment_entry);
+
+            follow_info->seq[is_server] += tail->data->len;
+            follow_info->bytes_written[is_server] += tail->data->len;
+            follow_info->payload = g_list_prepend(follow_info->payload, tail);
+            progress = true;
+            continue;
+        }
+
+        /* fragment->seq == next_offset: the fragment fills the gap. */
+        follow_info->seq[is_server] = frag_end;
+        follow_info->bytes_written[is_server] += fragment->data->len;
+        follow_info->payload = g_list_prepend(follow_info->payload, fragment);
+        follow_info->fragments[is_server] =
+            g_list_delete_link(follow_info->fragments[is_server], fragment_entry);
+        progress = true;
+    }
+
+    return progress;
