+/*
+ * Follow QUIC stream reassembly.
+ *
+ * QUIC STREAM frames carry absolute byte offsets, so their capture order need
+ * not match stream order. follow_info->payload is kept in reverse display
+ * order: the highest offset is nearest the list head and the lowest offset is
+ * at its tail. Records in that list never contain overlapping bytes. Gaps in
+ * a capture are left as gaps rather than inventing missing data.
+ *
+ * The generic follow infrastructure's 32 bit sequence fields are not needed
+ * here; QUIC reassembly itself is likewise limited to 32 bit offsets.
+ */
+
+typedef struct {
+    uint32_t start;
+    uint32_t end;
+} quic_follow_range_t;
+
+static gint
+quic_follow_payload_compare(gconstpointer a, gconstpointer b)
+{
+    const follow_record_t *ra = (const follow_record_t *)a;
+    const follow_record_t *rb = (const follow_record_t *)b;
+
+    /* Descending offset gives ascending output when traversing from tail. */
+    if (ra->seq > rb->seq)
+        return -1;
+    if (ra->seq < rb->seq)
+        return 1;
+    if (ra->packet_num > rb->packet_num)
+        return -1;
+    if (ra->packet_num < rb->packet_num)
+        return 1;
+    return 0;
+}
+
+static void
+quic_follow_add_record(follow_info_t *follow_info, bool is_server,
+                       uint32_t offset, const uint8_t *data, unsigned length,
+                       packet_info *pinfo)
+{
+    follow_record_t *record = g_new0(follow_record_t, 1);
+
+    record->is_server = is_server;
+    record->packet_num = pinfo->fd->num;
+    record->abs_ts = pinfo->fd->abs_ts;
+    record->seq = offset;
+    record->data = g_byte_array_new();
+    g_byte_array_append(record->data, data, length);
+
+    follow_info->bytes_written[is_server] += length;
+    follow_info->payload =
+        g_list_insert_sorted(follow_info->payload, record,
+                             quic_follow_payload_compare);
+}
